<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('information_officer');
$user = current_user();
$db = Database::getConnection();

function iod_e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function iod_has_table($db, string $table): bool {
    $s = $db->prepare('SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');
    if (!$s) return false;
    $s->bind_param('s', $table); $s->execute(); $ok = (bool)$s->get_result()->fetch_row(); $s->close(); return $ok;
}
function iod_has_column($db, string $table, string $column): bool {
    $s = $db->prepare('SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?');
    if (!$s) return false;
    $s->bind_param('ss', $table, $column); $s->execute(); $ok = (bool)$s->get_result()->fetch_row(); $s->close(); return $ok;
}
function iod_count($db, string $table, string $where = '1=1'): ?int {
    if (!iod_has_table($db, $table)) return null;
    $r = $db->query('SELECT COUNT(*) AS n FROM `' . str_replace('`', '', $table) . '` WHERE ' . $where);
    return $r ? (int)$r->fetch_assoc()['n'] : null;
}
function iod_rows($db, string $sql): array {
    $r = $db->query($sql); if (!$r) return [];
    $rows=[]; while ($row=$r->fetch_assoc()) $rows[]=$row; return $rows;
}
function iod_num($v): string { return $v === null ? '—' : number_format((int)$v); }

$profileLabel = trim((string)($user['full_name'] ?? $user['name'] ?? $user['username'] ?? 'Information Officer'));
$profileInitials = strtoupper(substr(preg_replace('/[^A-Za-z0-9]/', '', $profileLabel) ?: 'IO', 0, 2));
$today = date('Y-m-d');

// Main governance workload indicators. Missing optional tables are shown as unavailable, never as zero.
$openRequests = iod_count($db, 'io_data_subject_requests', "status NOT IN ('completed','rejected','closed')");
$overdueRequests = iod_count($db, 'io_data_subject_requests', "status NOT IN ('completed','rejected','closed') AND due_date IS NOT NULL AND due_date<CURDATE()");
$dueRequests = iod_count($db, 'io_data_subject_requests', "status NOT IN ('completed','rejected','closed') AND due_date=CURDATE()");
$openIncidents = iod_count($db, 'io_privacy_incidents', "status NOT IN ('closed','resolved')");
$urgentIncidents = iod_count($db, 'io_privacy_incidents', "status NOT IN ('closed','resolved') AND severity IN ('high','critical')");
$pendingAccess = iod_count($db, 'io_access_reviews', "status IN ('pending','in_progress','remediation_required')");
$dueAccess = iod_count($db, 'io_access_reviews', "status NOT IN ('completed','approved') AND due_date IS NOT NULL AND due_date<=CURDATE()");
$dueRetention = iod_count($db, 'io_retention_reviews', "status IN ('pending','review','deferred') AND due_date IS NOT NULL AND due_date<=CURDATE()");
$pendingRetention = iod_count($db, 'io_retention_reviews', "status IN ('pending','review','deferred')");
$consents = null;
if (iod_has_table($db, 'candidate_consents')) {
    $r=$db->query("SELECT COUNT(*) n FROM candidate_consents WHERE status='consented' AND (expires_at IS NULL OR expires_at>NOW())");
    if ($r) $consents=(int)$r->fetch_assoc()['n'];
}

// Document verification data is read only. It is available only when the main document table has the expected fields.
$docAvailable = iod_has_table($db, 'documents') && iod_has_column($db, 'documents', 'verification_status');
$docPending = $docVerified = $docRejected = $docTotal = null;
$recentDocuments = [];
if ($docAvailable) {
    $docTotal = iod_count($db, 'documents');
    $docPending = iod_count($db, 'documents', "LOWER(verification_status) IN ('unverified','pending','pending_verification','submitted','under_review')");
    $docVerified = iod_count($db, 'documents', "LOWER(verification_status) IN ('verified','approved','accepted')");
    $docRejected = iod_count($db, 'documents', "LOWER(verification_status) IN ('rejected','declined','invalid')");
    $dateColumn = iod_has_column($db, 'documents', 'created_at') ? 'created_at' : (iod_has_column($db, 'documents', 'uploaded_at') ? 'uploaded_at' : null);
    $select = ['id'];
    foreach (['document_type','verification_status','created_at','uploaded_at','updated_at'] as $col) if (iod_has_column($db,'documents',$col)) $select[]=$col;
    if ($dateColumn) $recentDocuments = iod_rows($db, 'SELECT '.implode(',',array_map(fn($c)=>'`'.$c.'`',$select)).' FROM `documents` ORDER BY `'.$dateColumn.'` DESC, id DESC LIMIT 6');
}

// Outstanding request queue: only operational metadata, no request descriptions or personal identifiers.
$outstanding = [];
if (iod_has_table($db,'io_data_subject_requests')) {
    $outstanding = iod_rows($db, "SELECT id, request_type, status, priority, due_date, received_at FROM io_data_subject_requests WHERE status NOT IN ('completed','rejected','closed') ORDER BY CASE priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END, (due_date IS NULL), due_date ASC, received_at ASC LIMIT 7");
}

// Upcoming compliance work combines review types without assuming all optional tables are installed.
$complianceTasks=[];
if (iod_has_table($db,'io_access_reviews')) {
    $complianceTasks = array_merge($complianceTasks, iod_rows($db, "SELECT 'Access review' AS task_type, review_name AS task, status, due_date FROM io_access_reviews WHERE status NOT IN ('completed','approved') ORDER BY (due_date IS NULL), due_date ASC LIMIT 6"));
}
if (iod_has_table($db,'io_retention_reviews')) {
    $complianceTasks = array_merge($complianceTasks, iod_rows($db, "SELECT 'Retention review' AS task_type, record_category AS task, status, due_date FROM io_retention_reviews WHERE status IN ('pending','review','deferred') ORDER BY (due_date IS NULL), due_date ASC LIMIT 6"));
}
usort($complianceTasks, function($a,$b){ $ad=$a['due_date']??''; $bd=$b['due_date']??''; if($ad===$bd)return strcmp($a['task_type'],$b['task_type']); if($ad==='')return 1; if($bd==='')return -1; return strcmp($ad,$bd); });
$complianceTasks=array_slice($complianceTasks,0,8);

// Recent actions come from this portal's audit trail, when installed and populated.
$recentActions=[];
if (iod_has_table($db,'io_audit_events')) {
    $recentActions = iod_rows($db, "SELECT action, entity_type, entity_id, outcome, created_at FROM io_audit_events ORDER BY created_at DESC, id DESC LIMIT 8");
}
$links = ['requests.php'=>'Data Subject Requests','incidents.php'=>'Privacy Incidents','consents.php'=>'Consent Monitoring','access_reviews.php'=>'Access Reviews','retention.php'=>'Retention Reviews','audit.php'=>'Audit Trail','reports.php'=>'Reports','settings.php'=>'Settings'];
function iod_status_class($status): string {
    $s=strtolower((string)$status);
    if (in_array($s,['urgent','critical','high','overdue','rejected','failure','denied','remediation_required'],true)) return 'danger';
    if (in_array($s,['pending','received','triage','in_progress','awaiting_subject','awaiting_approval','review','deferred','unverified','under_review'],true)) return 'warning';
    if (in_array($s,['completed','approved','verified','resolved','closed','success','accepted'],true)) return 'success';
    return 'neutral';
}
