nner .actions{margin-top:15px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.metric,.panel,.module{background:var(--card);border:1px solid var(--line);border-radius:15px;padding:18px;box-shadow:var(--shadow)}.metric{position:relative;overflow:hidden}.metric:before{content:"";position:absolute;inset:0 auto 0 0;width:4px;background:var(--ac)}.metric.alert:before{background:var(--red)}.metric .label{font-size:12px;color:var(--mut);font-weight:600;line-height:1.5}.metric .num{font-size:32px;font-weight:800;margin:12px 0 7px;letter-spacing:-.8px}.metric .hint{font-size:11px;color:var(--mut);min-height:17px}.metric a{display:inline-block;margin-top:12px;color:var(--ac);font-size:12px;font-weight:700;text-decoration:none}.section-title{margin:28px 0 12px;font-size:18px}.modules{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.module{text-decoration:none;color:var(--tx);transition:transform .15s,border-color .15s}.module:hover{transform:translateY(-2px);border-color:var(--ac)}.module .icon{width:38px;height:38px;border-radius:11px;background:var(--soft);display:grid;place-items:center;font-size:18px;margin-bottom:13px}.module strong{display:block;margin-bottom:7px}.module span{color:var(--mut);font-size:12px;line-height:1.55}.work-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:14px;margin-top:18px}.panel h2{font-size:16px;margin:0 0 6px}.panel .sub{font-size:12px;color:var(--mut);margin:0 0 14px;line-height:1.5}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--mut);font-size:10px;text-transform:uppercase;letter-spacing:.6px;white-space:nowrap}tbody tr:last-child td{border-bottom:0}.pill{display:inline-flex;align-items:center;border-radius:999px;padding:4px 8px;font-size:10px;font-weight:800;white-space:nowrap}.pill.danger{color:var(--red);background:var(--redbg)}.pill.warning{color:var(--amber);background:var(--amberbg)}.pill.success{color:var(--green);background:var(--greenbg)}.pill.neutral{color:var(--mut);background:var(--soft)}.empty{padding:18px 10px;text-align:center;color:var(--mut);font-size:12px}.text-link{color:var(--ac);font-weight:700;text-decoration:none;white-space:nowrap}.status-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)}.status-row:last-child{border-bottom:0}.status-row strong{display:block;font-size:12px}.status-row small{display:block;margin-top:4px;color:var(--mut);font-size:11px}.note{background:var(--soft);border-radius:10px;padding:13px;line-height:1.6;color:var(--tx);font-size:12px}.footer{padding:22px 0;color:var(--mut);font-size:11px}.quick-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.quick-links a{font-size:11px}@media(max-width:1050px){.cards,.modules{grid-template-columns:repeat(2,minmax(0,1fr))}.work-grid{grid-template-columns:1fr}}@media(max-width:600px){.wrap{padding:18px 12px}.cards,.modules{grid-template-columns:1fr}.metric .num{font-size:28px}.profile-chip{max-width:100%}.profile-chip span:last-child{max-width:155px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}th,td{padding:9px 7px}}
</style></head><body><main class="wrap">
<header class="top"><div><div class="eyebrow">Investhood IT · Governance & Compliance</div><h1>Information Officer Activity Dashboard</h1><div class="muted">Welcome, <?=iod_e($profileLabel)?>. Review today's workload, identify overdue items, and track recent governance activity.</div></div><div class="actions"><div class="profile-chip" aria-label="Signed in as <?=iod_e($profileLabel)?>"><span class="profile-avatar" aria-hidden="true"><?=iod_e($profileInitials)?></span><span><?=iod_e($profileLabel)?></span></div><button class="btn" id="themeToggle" type="button">Toggle theme</button><a class="btn" href="<?=iod_e(url('privacy/audit.php'))?>">Activity log</a><a class="btn primary" href="<?=iod_e(url('privacy/reports.php'))?>">View reports</a><a class="btn logout" href="<?=iod_e(url('auth/logout.php'))?>" aria-label="Log out and end your session" onclick="return confirm('Are you sure you want to log out?')">↪ Logout</a></div></header>
<section class="banner"><div class="eyebrow">Daily overview · <?=iod_e(date('l, j F Y'))?></div><h2>Keep requests, documents and compliance tasks moving</h2><p class="muted">This activity dashboard brings together document verification status, open information requests, privacy incidents, access reviews, retention work and recent actions. Figures reflect records available in the connected database; unavailable modules are marked rather than treated as zero.</p><div class="actions"><a class="btn primary" href="<?=iod_e(url('privacy/requests.php'))?>">＋ Register information request</a><a class="btn" href="<?=iod_e(url('privacy/incidents.php'))?>">＋ Report privacy incident</a><a class="btn" href="<?=iod_e(url('privacy/access_reviews.php'))?>">Plan access review</a></div></section>
<h2 class="section-title">Workload at a glance</h2><section class="cards">
<article class="metric <?=($overdueRequests??0)>0?'alert':''?>"><div class="label">Outstanding information requests</div><div class="num"><?=iod_num($openRequests)?></div><div class="hint"><?=($overdueRequests===null)?'Request register unavailable':iod_num($overdueRequests).' overdue · '.iod_num($dueRequests).' due today'?></div><a href="<?=iod_e(url('privacy/requests.php'))?>">Review request queue →</a></article>
<article class="metric <?=($docPending??0)>0?'alert':''?>"><div class="label">Documents awaiting verification</div><div class="num"><?=iod_num($docPending)?></div><div class="hint"><?=$docAvailable?iod_num($docVerified).' verified · '.iod_num($docRejected).' rejected':'Document verification data unavailable'?></div><a href="<?=iod_e(url('privacy/reports.php'))?>">View verification overview →</a></article>
<article class="metric <?=($urgentIncidents??0)>0?'alert':''?>"><div class="label">Open privacy incidents</div><div class="num"><?=iod_num($openIncidents)?></div><div class="hint"><?=($urgentIncidents===null)?'Incident register unavailable':iod_num($urgentIncidents).' high or critical priority'?></div><a href="<?=iod_e(url('privacy/incidents.php'))?>">Review incidents →</a></article>
<article class="metric <?=((($dueAccess??0)+($dueRetention??0))>0)?'alert':''?>"><div class="label">Compliance tasks due</div><div class="num"><?=($dueAccess===null&&$dueRetention===null)?'—':number_format((int)($dueAccess??0)+(int)($dueRetention??0))?></div><div class="hint"><?=iod_num($pendingAccess).' access reviews · '.iod_num($pendingRetention).' retention reviews open'?></div><a href="<?=iod_e(url('privacy/access_reviews.php'))?>">Review compliance work →</a></article>
</section>
<h2 class="section-title">Today's attention list</h2><section class="work-grid"><article class="panel"><h2>Outstanding information requests</h2><p class="sub">Prioritised by urgency and due date. Sensitive request descriptions are intentionally omitted from this overview.</p><div class="table-wrap"><table><thead><tr><th>Request</th><th>Priority</th><th>Status</th><th>Due</th></tr></thead><tbody>
<?php if(!$outstanding): ?><tr><td colspan="4" class="empty"><?=iod_has_table($db,'io_data_subject_requests')?'No outstanding requests found.':'Request register is not installed.'?></td></tr><?php else: foreach($outstanding as $row): $late=!empty($row['due_date'])&&$row['due_date']<$today; ?><tr><td><strong>#<?=iod_e($row['id'])?> · <?=iod_e(ucwords(str_replace('_',' ',$row['request_type'])))?></strong><div class="muted">Received <?=iod_e(substr((string)$row['received_at'],0,10))?></div></td><td><span class="pill <?=iod_status_class($row['priority'])?>"><?=iod_e(ucfirst($row['priority']))?></span></td><td><span class="pill <?=iod_status_class($row['status'])?>"><?=iod_e(ucwords(str_replace('_',' ',$row['status'])))?></span></td><td><?php if($late): ?><span class="pill danger">Overdue</span><div><?=iod_e($row['due_date'])?></div><?php else: ?><?=iod_e($row['due_date']?:'Not set')?><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="quick-links"><a class="text-link" href="<?=iod_e(url('privacy/requests.php'))?>">Open full request register →</a></div></article>
<article class="panel"><h2>Compliance tasks requiring follow-up</h2><p class="sub">Upcoming access and retention reviews. Check due dates, assign owners and record outcomes in the relevant register.</p>
<?php if(!$complianceTasks): ?><div class="empty"><?=iod_has_table($db,'io_access_reviews')||iod_has_table($db,'io_retention_reviews')?'No open compliance tasks found.':'Compliance review tables are not installed.'?></div><?php else: foreach($complianceTasks as $task): $late=!empty($task['due_date'])&&$task['due_date']<$today; ?><div class="status-row"><div><strong><?=iod_e($task['task'])?></strong><small><?=iod_e($task['task_type'])?> · Due <?=iod_e($task['due_date']?:'date not set')?></small></div><span class="pill <?=$late?'danger':iod_status_class($task['status'])?>"><?=$late?'Overdue':iod_e(ucwords(str_replace('_',' ',$task['status'])))?></span></div><?php endforeach; endif; ?>
<div class="quick-links"><a class="text-link" href="<?=iod_e(url('privacy/access_reviews.php'))?>">Access reviews →</a><a class="text-link" href="<?=iod_e(url('privacy/retention.php'))?>">Retention reviews →</a></div></article></section>
<section class="work-grid"><article class="panel"><h2>Document verification activity</h2><p class="sub">Read-only summary from the application's document register, where available.</p>
<?php if(!$docAvailable): ?><div class="note">The application document table or its verification status field is not available in this database. Document metrics will appear once the relevant document register is installed.</div><?php else: ?><div class="status-row"><div><strong>Total document records</strong><small>All records in the document register</small></div><strong><?=iod_num($docTotal)?></strong></div><div class="status-row"><div><strong>Awaiting verification</strong><small>Unverified, submitted or under review</small></div><span class="pill <?=($docPending??0)>0?'warning':'success'?>"><?=iod_num($docPending)?></span></div><div class="status-row"><div><strong>Verified / approved</strong><small>Records marked as accepted or verified</small></div><span class="pill success"><?=iod_num($docVerified)?></span></div><div class="status-row"><div><strong>Rejected / invalid</strong><small>May require follow-up by the responsible team</small></div><span class="pill <?=($docRejected??0)>0?'danger':'neutral'?>"><?=iod_num($docRejected)?></span></div><?php if($recentDocuments): ?><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Record</th><th>Type</th><th>Status</th><th>Added</th></tr></thead><tbody><?php foreach($recentDocuments as $doc): $dDate=$doc['created_at']??$doc['uploaded_at']??$doc['updated_at']??''; ?><tr><td>#<?=iod_e($doc['id'])?></td><td><?=iod_e($doc['document_type']??'Document')?></td><td><span class="pill <?=iod_status_class($doc['verification_status']??'unknown')?>"><?=iod_e(ucwords(str_replace('_',' ',$doc['verification_status']??'Unknown')))?></span></td><td><?=iod_e(substr((string)$dDate,0,10)?:'—')?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php endif; ?></article>
<article class="panel"><h2>Recent actions</h2><p class="sub">Latest actions recorded by the Information Officer portal audit trail.</p><?php if(!$recentActions): ?><div class="empty"><?=iod_has_table($db,'io_audit_events')?'No audit actions recorded yet.':'Audit trail is not installed.'?></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Action</th><th>Record</th><th>Outcome</th><th>When</th></tr></thead><tbody><?php foreach($recentActions as $action): ?><tr><td><?=iod_e(ucwords(str_replace('_',' ',$action['action'])))?></td><td><?=iod_e(trim(($action['entity_type']??'').(!empty($action['entity_id'])?' #'.$action['entity_id']:''))?:'—')?></td><td><span class="pill <?=iod_status_class($action['outcome'])?>"><?=iod_e(ucfirst($action['outcome']))?></span></td><td><?=iod_e(substr((string)$action['created_at'],0,16))?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><div class="quick-links"><a class="text-link" href="<?=iod_e(url('privacy/audit.php'))?>">Open full activity log →</a></div></article></section>
<h2 class="section-title">Information Officer workspace</h2><section class="modules"><?php $items=[['requests.php','▤','Data Subject Requests','Register and review access, correction and other requests.'],['incidents.php','!','Privacy Incidents','Document and monitor suspected or confirmed privacy incidents.'],['consents.php','✓','Consent Monitoring','Review consent status summaries.'],['access_reviews.php','⌕','Access Reviews','Plan periodic reviews of role and privileged access.'],['retention.php','◷','Retention Reviews','Track retention decisions, due dates and legal holds.'],['audit.php','≡','Audit Trail','Review activity logged by this portal.'],['reports.php','▥','Reports & Metrics','View operational counts and print reports.'],['settings.php','⚙','Governance Guidance','Review operational control and policy checklist.']];foreach($items as $it):?><a class="module" href="<?=iod_e(url('privacy/'.$it[0]))?>"><div class="icon"><?=iod_e($it[1])?></div><strong><?=iod_e($it[2])?></strong><span><?=iod_e($it[3])?></span></a><?php endforeach;?></section>
<section class="work-grid"><article class="panel"><h2>Daily control checklist</h2><div class="status-row"><div><strong>Check overdue requests</strong><small>Review ownership, priority and response deadlines.</small></div><span class="pill <?=($overdueRequests??0)>0?'danger':'success'?>"><?=($overdueRequests===null)?'Unavailable':(($overdueRequests>0)?'Action needed':'On track')?></span></div><div class="status-row"><div><strong>Review high-severity incidents</strong><small>Follow approved incident response and escalation procedures.</small></div><span class="pill <?=($urgentIncidents??0)>0?'danger':'success'?>"><?=($urgentIncidents===null)?'Unavailable':(($urgentIncidents>0)?'Action needed':'No open high priority')?></span></div><div class="status-row"><div><strong>Check review due dates</strong><small>Confirm access and retention tasks have owners and outcomes.</small></div><span class="pill <?=((($dueAccess??0)+($dueRetention??0))>0)?'warning':'success'?>"><?=($dueAccess===null&&$dueRetention===null)?'Unavailable':(((int)($dueAccess??0)+(int)($dueRetention??0)>0)?'Due':'No overdue tasks')?></span></div></article><article class="panel"><h2>Data and compliance note</h2><div class="note">Dashboard figures are operational indicators, not proof of regulatory compliance. Document verification is shown read-only; this dashboard does not approve documents, alter consent, automatically delete records, or notify regulators or affected individuals. Follow your organisation's approved procedures and permissions.</div><p class="muted">Last refreshed: <?=iod_e(date('j M Y, H:i'))?></p></article></section>
<footer class="footer">Information Officer workspace · Use authorised access and follow approved privacy policies.</footer></main><script>const root=document.documentElement;try{if(localStorage.getItem('io-theme')==='dark')root.dataset.theme='dark'}catch(e){}document.getElementById('themeToggle').addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('io-theme',root.dataset.theme)}catch(e){}});</script></body></html>
